	title 'QD Cursor            GS ROM 3.0'*****************************************************************			   **                   CURSOR		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1989	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   ***************************************************************************************************************************************** Change History** 11 Nov 88	Steven Glass** Changed ShieldCursor, UpdateCursor and RefreshCursor to kill * bug related to shielded obscured cursors.  If an obscured cursor* was shielded, and it moved, it was redrawn anyway (leaving cursor* droppings on the screen).  This happened because ShieldCursor* did not mark the cursor as busy if it was obscured.  Now it* is marked busy no matter what.** UpdateCursor and RefreshCursor changed to mark the cursor* as shielded if the cursor moved while it was obscured and busy.* Without this change, the cursor could be undrawn even when it* was not visible, leaving cursor droppings on the screen.** 2/1/89	Mensch** Modified to shield when drawing to regular and shadowed screen****  3/20/89	Mark Cecys**  Added "MIDIInputPoll" in time-consumming routines. If assem directive "midi"*  is set to one, then polling will be assembled, otherwise if set to zero,*  no MIDI polling will be added. This is used by MidiTools which patches in*  its local cursor routines to prevent SCC over-run. (QD makefile has midi=0)*  The following PROC's are affected:**	UserInitCursor*	CalcSaveSize*	iDrawCursor*	iUndrawCursor***  24 Apr 89	Steven Glass**  Fixed bug in UpdateCursor relating to the UseInterrupts Flag*  BRC #48180***********************************************************************	include 'all.macros'	MACRO&lab	MoveLong &From,&To&lab	lda &From	sta &To	lda &From+2	sta &To+2	MEND	include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:core.globals1'	include '::sys.equs.asm'		title 'Cursor Equates'ScreenStart	equ $2000ScreenHeight	equ 200	; number of scan linesScreenWidth	equ 160	; number of bytesMaxWidth	equ 32	; max number of bytes containing*		; single line of cursor image.;-----------------------------------------------;; We start the cursor data on zero page	at the end; of the stuff used	by the rest of quickdraw.;StartofZP	equ CursorSTARTUseInterrupts	equ StartofZPIntPending	equ UseInterrupts+2MouseY	equ IntPending+2MouseX	equ MouseY+2NextMouseY	equ MouseX+2NextMouseX	equ NextMouseY+2CurHeight	equ NextMouseX+2	; Num scan lines high of cursorCurWidth	equ CurHeight+2	; Num WORDS wide of	cursorCursorRect	equ CurWidth+2CursorY1	equ CursorRectCursorX1	equ CursorY1+2CursorY2	equ CursorX1+2CursorX2	equ CursorY2+2CursorMode	equ CursorX2+2CursorRecPtr	equ CursorMode+2CursorPtr	equ CursorRecPtr+4MaskPtr	equ CursorPtr+4CursorPtr1	equ MaskPtr+4MaskPtr1	equ CursorPtr1+4CursorPtr2	equ MaskPtr1+4MaskPtr2	equ CursorPtr2+4CursorPtr3	equ MaskPtr2+4MaskPtr3	equ CursorPtr3+4CursorPtr4	equ MaskPtr3+4MaskPtr4	equ CursorPtr4+4CursorPtr5	equ MaskPtr4+4MaskPtr5	equ CursorPtr5+4CursorPtr6	equ MaskPtr5+4MaskPtr6	equ CursorPtr6+4CursorPtr7	equ MaskPtr6+4MaskPtr7	equ CursorPtr7+4SaveHandle	equ MaskPtr7+4SavePtr	equ SaveHandle+4SaveSize	equ SavePtr+4CursorRef	equ SaveSize+2MaskRef	equ CursorRef+4HotSpot	equ MaskRef+4SaveRef	equ HotSpot+4ScreenRef	equ SaveRef+4CursorLevel	equ ScreenRef+2ObscureFlag	equ CursorLevel+2StartWord	equ ObscureFlag+2ScreenIndex	equ StartWord+2SaveIndex	equ ScreenIndex+2CurrentY	equ SaveIndex+2ThisOut	equ CurrentY+2LastOut	equ ThisOut+2SrcRef	equ LastOut+2DestRef	equ SrcRef+4ThisWord	equ DestRef+4HowManyWords	equ ThisWord+2WordCount	equ HowManyWords+2LineCount	equ WordCount+2HowFarToShift	equ LineCount+2CursorFlags	equ HowFarToShift+2TempRect	equ CursorFlags+2SaveRect	equ TempRect+8ZZEndofCursor	equ SaveRect+8Busy_M	equ $8000Shielded_M	equ $4000ForceU_M	equ $2000	title 'Cursor Imports and Entries';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT BusyEC0	IMPORT BusyEC2	IMPORT BusyEC4	IMPORT BusyErr0	IMPORT BusyErr4	IMPORT QDStart	IMPORT SpecialNewHandle	IMPORT xShiftOut	IMPORT xShiftStay;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY CalcSaveSize	ENTRY ClearSCB	ENTRY GetItReady	ENTRY RefreshCursor	ENTRY ShiftOne	ENTRY UpdateCursor	title 'CursorData'CursorDATA	PROC EXPORT	EXPORT Arrow320Arrow320		; 	DC.W 11,4	; 11 scan lines by 4 words*     0 2 4 6 8 A C	E	DC.B $00,$00,$00,$00,$00,$00,$00,$00 ; 1	DC.B $0F,$00,$00,$00,$00,$00,$00,$00 ; 2	DC.B $0F,$F0,$00,$00,$00,$00,$00,$00 ; 3	DC.B $0F,$FF,$00,$00,$00,$00,$00,$00 ; 4	DC.B $0F,$FF,$F0,$00,$00,$00,$00,$00 ; 5	DC.B $0F,$FF,$FF,$00,$00,$00,$00,$00 ; 6	DC.B $0F,$FF,$FF,$F0,$00,$00,$00,$00 ; 7	DC.B $0F,$FF,$FF,$FF,$00,$00,$00,$00 ; 8	DC.B $0F,$F0,$FF,$00,$00,$00,$00,$00 ; 9	DC.B $00,$00,$0F,$F0,$00,$00,$00,$00 ; 10	DC.B $00,$00,$00,$00,$00,$00,$00,$00 ; 11*     0 2 4 6 8 A C	E	DC.B $FF,$00,$00,$00,$00,$00,$00,$00 ; 1	DC.B $FF,$F0,$00,$00,$00,$00,$00,$00 ; 2	DC.B $FF,$FF,$00,$00,$00,$00,$00,$00 ; 3	DC.B $FF,$FF,$F0,$00,$00,$00,$00,$00 ; 4	DC.B $FF,$FF,$FF,$00,$00,$00,$00,$00 ; 5	DC.B $FF,$FF,$FF,$F0,$00,$00,$00,$00 ; 6	DC.B $FF,$FF,$FF,$FF,$00,$00,$00,$00 ; 7	DC.B $FF,$FF,$FF,$FF,$F0,$00,$00,$00 ; 8	DC.B $FF,$FF,$FF,$FF,$00,$00,$00,$00 ; 9	DC.B $FF,$F0,$FF,$FF,$00,$00,$00,$00 ; 10	DC.B $00,$00,$0F,$FF,$00,$00,$00,$00 ; 11	DC.W 1,1	; hot spot	EXPORT Arrow640Arrow640		; 	DC.W 11,2	; 11 scan lines by 2 words*     0   2   4   6	  8   A   C   E	DC.B %00000000,%00000000,%00000000,%00000000 ; 1	DC.B %00110000,%00000000,%00000000,%00000000 ; 2	DC.B %00111100,%00000000,%00000000,%00000000 ; 3	DC.B %00111111,%00000000,%00000000,%00000000 ; 4	DC.B %00111111,%11000000,%00000000,%00000000 ; 5	DC.B %00111111,%11110000,%00000000,%00000000 ; 6	DC.B %00111111,%11111100,%00000000,%00000000 ; 7	DC.B %00111111,%11111111,%00000000,%00000000 ; 8	DC.B %00111100,%11110000,%00000000,%00000000 ; 9	DC.B %00000000,%00111100,%00000000,%00000000 ; 10	DC.B %00000000,%00000000,%00000000,%00000000 ; 11*     0   2   4   6	  8   A   C   E	DC.B %11110000,%00000000,%00000000,%00000000 ; 1	DC.B %11111100,%00000000,%00000000,%00000000 ; 2	DC.B %11111111,%00000000,%00000000,%00000000 ; 3	DC.B %11111111,%11000000,%00000000,%00000000 ; 4	DC.B %11111111,%11110000,%00000000,%00000000 ; 5	DC.B %11111111,%11111100,%00000000,%00000000 ; 6	DC.B %11111111,%11111111,%00000000,%00000000 ; 7	DC.B %11111111,%11111111,%11000000,%00000000 ; 8	DC.B %11111111,%11111111,%11000000,%00000000 ; 9	DC.B %11111100,%11111111,%00000000,%00000000 ; 10	DC.B %00000000,%11111111,%00000000,%00000000 ; 11	DC.W 1,1	; hot spot	ENDP	title 'InitCursor'****************************************************************** InitCursor** This is not an entry point!  This is the routine called* at quickdraw startup time.*****************************************************************InitCursor	PROC EXPORT	tdc	; get direct reg in	a	tax	; and in x	phd	; initialize some stuff	clc	adc #$100	tcd	lda >UserID,x	tax	lda #$400	ldy #$8000	jsr SpecialNewHandle	bcc GotHandle	jmp ErrorOutGotHandle		; ; dereference the	locked handle	stx SaveHandle	sty SaveHandle+2	ldy #2	lda [SaveHandle],y	sta SavePtr+2	lda [SaveHandle]	sta SavePtr	jsr GetItReady	bcs ErrorOut	pha	; save the old value of the Scan	pha	; line interrupt vector	PushWord #ScanIntRefNum	_GetVector	pla	sta >OldScanInt	pla	sta >OldScanInt+2	PushWord #CurUpdateRefNum ; install pointer to update	PushLong #UpdateCursor ; cursor routine	_SetVector	PushWord #ScanIntRefNum ; install pointer to	PushLong #RefreshCursor ; cursor refresh routine	_SetVector	PushWord #EnableScanInts ; turn on scan	line interrupts.	_IntSource	lda #$8000	; set zero page flag	sta UseInterrupts	pld	lda #0	; signal no error	clc	rtlErrorOut	pld	rtl	ENDP	title 'GetItReady'****************************************************************** GetItReady** This routine sets	up the cursor mode and calls set cursor.*****************************************************************GetItReady	PROC EXPORT	tdc	; get the zp adr	sec	; subtract $100	sbc #$100	tax	; put in x	lda >MasterSCB,x	; move masterSCB from	sta CursorMode	; QD zp to cursor ZP	stz ObscureFlag	; clear the obscure	flag	lda #$FFFF	; and set cursor not visible	sta CursorLevel;-------------------------------------------------;; Now set up a cursor	bit CursorMode-1	bmi Mode640	PushLong #Arrow320	bra CallItMode640	PushLong #Arrow640CallIt	_SetCursor	rts	ENDP	title 'UserInitCursor'****************************************************************** UserInitCursor** This is the entry	point for the user to restore the standard* cursor for the current MasterSCB.*****************************************************************UserInitCursor	PROC EXPORT	jsr QDStart	clc	adc #$100	tcd	php	sei	_HideCursor	; always hide	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	jsr GetItReady	; reset everything	bcs Error	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	_ShowCursor	; show it now that all is resetAllDone	plp	jmp BusyEC0Error	plp	; restore interrupts	tax	; put error in x	jmp BusyErr0	; get out	ENDP	title 'Lock and Unlock SaveHandle'****************************************************************** LockSaveHandle** Internal Routine to quickly lock and dereference the save	handle.* Relies on fact that lock bit is kept in word immediatly after pointer* to data.*****************************************************************LockSaveHandle	PROC EXPORT	ldy #4	lda [SaveHandle],y	ora #$8000	sta [SaveHandle],y	lda [SaveHandle]	sta SavePtr	ldy #2	lda [SaveHandle],y	sta SavePtr+2	rts	ENDP****************************************************************** UnlockSavehandle** Internal routine to quickly unlock the save handle* Relies on fact that lock bit is kept in word immediatly* after pointer to data.*****************************************************************UnlockSaveHandle	PROC EXPORT	ldy #4	lda [SaveHandle],y	and #$7FFF	sta [SaveHandle],y	rts	ENDP	title 'CursorShutdown'****************************************************************** CursorShutDown** Frees up the memory used to save the cursor.*****************************************************************CursorShutDown	PROC EXPORT	phd	tdc	clc	adc #$100	tcd	PushWord #DisableScanInts ; turn on scan line interrupts.	_IntSource	stz UseInterrupts	pei SaveHandle+2	pei SaveHandle	_DisposeHandle	PushWord #ScanIntRefNum ; restore the old value of the scan	lda >OldScanInt+2	; line interrupt vector!	pha	lda >OldScanInt	pha	_SetVector	pld	rts	ENDP	title 'ShiftStuff'****************************************************************** ShiftStuff** This creates the preshifted cursor images used later.*****************************************************************ShiftStuff	PROC EXPORT	ldx #0	bit CursorMode-1	bmi Mode640	lda #8	; 4 * 2	sta HowFarToShiftLoop320		; 	jsr DoPair	lda HowFarToShift	clc	adc #8	sta HowFarToShift	cpx #24	bcc Loop320	rtsMode640	lda #4	; 2 * 2	sta HowFarToShiftLoop640		; 	jsr DoPair	lda HowFarToShift	clc	adc #4	sta HowFarToShift	cpx #56	bcc Loop640	rtsDoPair		; 	MoveLong MaskPtr,SrcRef	lda MaskPtr1,x	sta DestRef	lda MaskPtr1+2,x	sta DestRef+2	phx	jsr ShiftOne	plx	MoveLong CursorPtr,SrcRef	lda CursorPtr1,x	sta DestRef	lda CursorPtr1+2,x	sta DestRef+2	phx	jsr ShiftOne	plx	txa	clc	adc #8	tax	rts	ENDP	title 'More Shift Stuff'ShiftOne	PROC EXPORT	lda CurHeight	sta LineCountBigLoop		; 	lda CurWidth	; put num words - 1	in wordcount	dec a	sta WordCount	stz LastOut	ldy #0	; start with first wordShiftLoop	lda [SrcRef],y	sta ThisWord	ldx HowFarToShift	jsl xShiftOut	sta ThisOut	lda ThisWord	ldx HowFarToShift	jsl xShiftStay	ora LastOut	sta [DestRef],y	lda ThisOut	; move shift outs	sta LastOut	iny	iny	dec WordCount	bpl ShiftLoop	lda CurWidth	; num words	asl a	; make into bytes	tax	; save copy in x	clc	; bump srcref	adc SrcRef	sta SrcRef	txa	; use copy in x again	clc	; bump destref	adc DestRef	sta DestRef	dec LineCount	bpl BigLoop	rts	ENDP	title 'SetCursor'****************************************************************** SetCursor** Input*     CursorPtr   long    Points to cursor record*** The memory pointed to by SavePtr is organized as follows:**      SaveArea	 SaveSize*      CursorImage1	 SaveSize*      MaskImage1	 SaveSize*      CursorImage2	 SaveSize*      MaskImage2	 SaveSize*      CursorImage3	 SaveSize*      MaskImage3	 SaveSize*      CursorImage4	 SaveSize       needed for 640 mode*      MaskImage4	 SaveSize*      CursorImage5	 SaveSize*      MaskImage5	 SaveSize*      CursorImage6	 SaveSize*      MaskImage6	 SaveSize*      CursorImage7	 SaveSize*      MaskImage7	 SaveSize** The total memory I need is 7 * SaveSize in 320 mode* and 15 * SaveSize	in 640 mode.* ****************************************************************SetCursor	PROC EXPORTOrigP	equ 1OrigDirect	equ OrigP+1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheCursorPtr	equ RTL2+3	jsr QDStart	clc	adc #$100	tcd	php	; save PROC EXPORTessor	sei	; turn off interrupts to do this	bit CursorLevel	bmi NotVisible	bit ObscureFlag	bmi NotVisible	jsl UnDrawCursor	; restore under cursorNotVisible		; 	jsr CalcSaveSize	pha	; put new save size	on stack;----------------------------------------------; Now I need some memory to use for the	save; area, and the preshifted cursor images.;; The amount I need	is equal to;;      SaveSize (for saving) +;      6 * SaveSize	(for 320 mode)  = 7	* SaveSize;;      14 * SaveSize (for 640 mode) = 15 * SaveSize;	jsr UnlockSaveHandle	lda 1,s	asl a	asl a	asl a	bit CursorMode-1	bpl ThatsEnough	asl aThatsEnough	sec	sbc 1,s	pea 0	pha	pei SaveHandle+2	pei SaveHandle	_SetHandleSize	bcc NoProblem	pha	jsr LockSaveHandle	bit CursorLevel	bmi StillNotVisible	bit ObscureFlag	bmi StillNotVisible	jsl DrawCursorStillNotVisible	plx	; put error in x	pla	; get new save size	off stack	plp	; restore PROC EXPORTessor	jmp BusyErr4	; quit and return errorNoProblem		; 	jsr LockSaveHandle	plx	; get save size in x so stack is right	lda TheCursorPtr,s	; get pointer to cursor rec	sta CursorRecPtr	lda TheCursorPtr+2,s	sta CursorRecPtr+2	lda [CursorRecPtr]	; I move height and	width	sta CurHeight	; to zero page	ldy #2	lda [CursorRecPtr],y	sta CurWidth	lda CursorRecPtr	; point to cursor image	clc	adc #4	sta CursorPtr	lda CursorRecPtr+2	sta CursorPtr+2	txa	; get savesize in a	sta SaveSize	sec	; get rid of extra word per line	sbc CurHeight	sec	sbc CurHeight	tay	; put copy in Y too	clc	adc CursorPtr	sta MaskPtr	lda CursorPtr+2	sta MaskPtr+2	lda [MaskPtr],y	; get hot spot	sta HotSpot	iny	iny	lda [MaskPtr],y	sta HotSpot+2;----------------------------------------------;; Update the appropriate pointers.;	lda SavePtr	; the first pointer	is savesize past	clc	; saveptr.	adc SaveSize	sta CursorPtr1	lda SavePtr+2	adc #0	sta CursorPtr1+2	ldx #0SetUpLoop	lda CursorPtr1,x	clc	adc SaveSize	sta CursorPtr1+4,x	lda CursorPtr1+2,x	adc #0	sta CursorPtr1+6,x	inx	inx	inx	inx	cpx #13*4	; 52, 7 sets of two	pointers	bcc SetUpLoop;----------------------------------------------;; Now I must shift the cursor and mask into; the appropriate places.;	jsr ShiftStuff;----------------------------------------------;; Now I can show the new cursor;	bit CursorLevel	bmi DoNotShow	bit ObscureFlag	; or should a set cursor unobscure it?	bmi DoNotShow	jsl DrawCursorDoNotShow	plp	; restore interrupt	status	jmp BusyEC4	ENDP	title 'CalcSaveSize'********************************************************************************************************************************CalcSaveSize	PROC EXPORTCurDirect	equ 1ThisRTS	equ CurDirect+2OrigP	equ ThisRTS+2OrigDirect	equ OrigP+1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheCursorPtr	equ RTL2+3	phd	tsc	tcd	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	PushLong #0	lda [TheCursorPtr]	pha	ldy #2	lda [TheCursorPtr],y	inc a	; add 1	asl a	; and double in words	pha	_Multiply	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	pla	; result in a	plx	; ignore high word	pld	; restore direct register	rts	; all done	ENDP	title 'GetCursorAdr'****************************************************************** GetCursorAdr** Output*     CursorPtr   long    Points to cursor record*****************************************************************GetCursorAdr	PROC EXPORTOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheCursorPtr	equ RTL2+3	jsr QDStart	clc	adc #$100	tcd	lda CursorRecPtr	sta TheCursorPtr,s	lda CursorRecPtr+2	sta TheCursorPtr+2,s	jmp BusyEC0	ENDP	title 'ShowCursor'****************************************************************** ShowCursor** Increments the cursor level.*** Change History** August 21, 1986 SEG   Check for obscure flag is now added.*	    Obscured cursor	is correctly displayed*	    by showcursor call.** 10 Oct 1986  SEG	   A new problem was found.  When this patch*	   ran with the cursor obscured and hidden,*	   the cursor stayed hidden after the show*	   call.**	   Example:*	             ObscureCursor*	             HideCursor*	             ShowCursor**	   To fix this I do	not decrement the*	   cursor level when the cursor is obscured*	   if the cursor is	already hidden.*****************************************************************ShowCursor	PROC EXPORT	jsr QDStart	clc	adc #$100	tcd	php	sei	bit ObscureFlag	; Check the obscure	flag	bpl NoProblem	stz ObscureFlag	; clear the flag	lda CursorLevel	; no look at the cursor level.	bmi NoProblem	; if it negative there is nothing more*		; to do	dec CursorLevel	; If zero, dec the cursor level*		; so rest of this routine will do*		; the right thing.NoProblem	inc CursorLevel	bmi AllDone	lda CursorLevel	bne AlreadyVisable	jsl DrawCursorAlreadyVisable	stz CursorLevelAllDone	plp	jmp BusyEC0	ENDP	title 'HideCursor'****************************************************************** HideCursor** Decrements the cursor level.** Change History** 10 Oct 1986      SEG       If the cursor was obscured*	         this routine undrew it again*	         anyway.  This left strange looking*	         images on the screen.**	         Now we just decrement the level if*	         cursor is obsured.*****************************************************************HideCursor	PROC EXPORT	jsr QDStart	clc	adc #$100	tcd	php	sei	lda CursorLevel	bmi NotVisible	bit ObscureFlag	; if obscured, then	don't undraw!	bmi NotVisible	jsl UndrawCursor	; it was vis and not obscuredNotVisible	dec CursorLevel	; always dec level	plp	jmp BusyEC0	ENDP	title 'ObscureCursor'****************************************************************** ObscureCursor** Sets the obscure flag.*****************************************************************ObscureCursor	PROC EXPORT	jsr QDStart	clc	adc #$100	tcd	php	sei	lda CursorLevel	bmi NotVisible	lda ObscureFlag	bmi NotVisible	jsl UndrawCursorNotVisible	lda #$8000	sta ObscureFlag	plp	jmp BusyEC0	ENDP	title 'ShieldCursor'****************************************************************** ShieldCursor** This Routine marks the cursor busy and if the min rect and* cursor rect intersect, it hides the cursor** Change History** 21 Aug 86     SEG	   Shield cursor made a 4 byte compare*      to see if the current port is the*      screen to decide if the cursor should*      be shielded.	 It now does a 3 byte compare*      so that system windows will work	correctly.** 11 Nov 88     SEG	   Cursor is always	marked busy when this*      routine is called.  (Used to only be*      marked busy if the cursor was visible--*      level positive and not obscured.)** 2/24/89	Mensch** Changed the direct page setup and moved some of the compares around* this should be a 100% speed increase if no shielding is to take place*****************************************************************iShieldCursor	PROC EXPORT	ldx #$0100	; used as an index throughout;-------------------------------------------------;; No matter what, set the cursor busy flag.; Used to only set it if the cursor was	visible.;	lda #Busy_M	sta <CursorFlags,x;-------------------------------------------------;; If the cursor is not visible, it cannot be made; visible until after the drawing call is complete; so don't worry.;	bit <CursorLevel,x	bmi NeverMind	bit <ObscureFlag,x	bmi NeverMind;-------------------------------------------------;; Is this drawing going to be to the screen?; If not then don't bother.;	lda ImageRef	cmp #$2000	bne NeverMind	lda ImageRef+1	; I only care about	3 bytes in;; EXP 1/25/89; take shadowing into account here!;	and #$0FFF	; strip off the high bank nibble to accomodate shadowing	cmp #$0120	; the pointer so that system windows	bne NeverMind	; will work  21 Aug	86;-------------------------------------------------;; Now decide if the	MinRect of the drawing and; the cursor rect intersect.;	lda MinRect	; get top of min rect	sec	; and convert to global	sbc BoundsRect	; coordinates	cmp <SaveRect,x	bpl MinTopGreater	lda <SaveRect,xMinTopGreater	sta <TempRect,x	lda MinRect+4	; get bot of min rect	sec	; and convert to global	sbc BoundsRect	; coordinates	cmp <SaveRect+4,x	bmi MinBotLess	lda <SaveRect+4,xMinBotLess		cmp <TempRect,x	bmi NeverMind			lda MinRect+2	; get left of min rect	sec	; and convert to global	sbc BoundsRect+2	; coordinates	cmp <SaveRect+2,x	bpl MinLeftGreater	lda <SaveRect+2,xMinLeftGreater	sta <TempRect,x	lda MinRect+6	; get right of min rect	sec	; and convert to global	sbc BoundsRect+2	; coordinates	cmp <SaveRect+6,x	bmi MinRightLess	lda <SaveRect+6,xMinRightLess		cmp <TempRect,x	bmi NeverMind;-------------------------------------------------;; Yes they intersect so hide the cursor.;	phd	; save the direct reg	tdc	; get it	clc	adc #$100	; add 100 and put back in d	tcd	jsl UnDrawCursor	; undraw it	lda #Shielded_M	tsb CursorFlags	ldx #$0100	pld	; restore direct registerNeverMind	rtl	ENDP	title 'UnShieldCursor'****************************************************************** UnShieldCursor** This Routine undoes the work of ShieldCursor above.*****************************************************************iUnShieldCursor	PROC EXPORT	phd	; save the direct reg	tdc	; get it	tax	; put copy in x	clc	adc #$100	; add 100 and put back in d	tcd;-------------------------------------------------;; If the cursor is not shielded, then I	don't have; to unshield it now.;	bit CursorFlags	bvs YesShielded	lda #ForceU_M	and CursorFlags	beq NeverMind	jsl UnDrawCursor	; have moved so undraw it and draw again;-------------------------------------------------;; Yes they intersect so hide the cursor.;YesShielded		; 	jsl DrawCursor	; draw itNeverMind	stz CursorFlags	; clear cursor busy	pld	; restore direct register	rtl	ENDP	title 'SetMouseLoc'****************************************************************** SetMouseLoc**              MouseX  word*              MouseY  word** Test call that moves the mouse position.*****************************************************************SetMouseLoc	PROC EXPORTOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheMouseY	equ RTL2+3TheMouseX	equ TheMouseY+2	jsr QDStart	clc	adc #$100	tcd	bit CursorLevel	bmi NotVis1	bit ObscureFlag	bmi NotVis1;-------------------------------------------------;; Undraw last one;	phx	jsl UnDrawCursor	plx;-------------------------------------------------;; Set new mouse pos;NotVis1	lda TheMouseY,s	sta MouseY	lda TheMouseX,s	sta MouseX	bit CursorLevel	bmi NotVis2	bit ObscureFlag	bmi NotVis2;-------------------------------------------------;; Draw it in new place;	jsl DrawCursorNotVis2	jmp BusyEC4	ENDP	title 'SetIntUse'****************************************************************** SetIntUse   (YesOrNo : boolean);** If user sends non	zero value, I set int use to yes.  If* user sends in zero value, I set int use to no.*****************************************************************SetIntUse	PROC EXPORTOrigP	equ 1OrigDirect	equ OrigP+1RTL1	equ OrigDirect+2RTL2	equ RTL1+3YesOrNo	equ RTL2+3	jsr QDStart	clc	adc #$100	tcd	php	; save PROC EXPORTessor	sei	; turn off interrupts to do this	lda YesOrNo,s	beq StoreIt	lda #$8000StoreIt	sta UseInterrupts	plp	jmp BusyEC2	ENDP	title 'UpdateCursor'*****************************************************************UpdateCursor	PROC EXPORT** This routine is called through a vector in bank E1.  When* I get control, there are three bytes of return address info* on the stack followed by 4 bytes of mouse information.** The calling routine expects me to clean the inputs* off the stack.** This routine checks the UseInterrupts	flag on zero page* to decide whether	to draw the cursor immediately or* arrange for an intterupt to occur later.** If I arrange for later, this routine puts the next* mouse position on	zero page and turns	on interrupts for* the scan line the	mouse is going to be on.** Notes:*        The interrupt service routine will always clear*        the SCB so	that only one line has the int on it*        at a time.	     **** Inputs:*	direct page and stack*          Stack*	MouseX : word*	MouseY : word*** Outputs:*	none** External Refs:	import HandleCursor** Entry Points:*	none*	longa on	; mode	longi on** Change History** 11 Nov 88	Steven Glass** Cursor is marked shielded if it was obscured and it was* supposed to be drawn but it was busy.  This prevents it * from being undrawn later when cursor is unshielded.** 11 Dec 88	Steven Glass** Changed code to call HandleCursor instead of having code in* line in both the UpdateCursor and RefreshCursor routines.** 24 Apr 89	Steven Glass** Fixed bug introduced on 11 Dec where nextMouse was not* updated if UseInterrupts was zero.*****************************************************************OrigDirect	equ 1WorkAreaRef	equ OrigDirect+2RTLAdr	equ WorkAreaRef+4TheMouseY	equ RTLAdr+3TheMouseX	equ TheMouseY+2;-------------------------------------------------;; Find our zero page.;	lda >WAPTPtr+2	pha	lda >WAPTPtr	pha	phd	tsc	tcd	ldy #16	lda [WorkAreaRef],y	beq CleanUp	; not initialized so quit	clc	; now add $100	adc #$100	; and put in direct	reg	tcd; 26 Apr 89 Mensch and Steve Glass; This routine was not clearing the proper scan line interupt after the 4/24 fix.; due to nextMouseY being updated too soon. This is no longer the case. Also, the; ClearSCB routine is called ALL the time now if you have interupts turned on; (this is due to the fact that it can't every hurt to clear the interupt cause it; belongs to us, and we set it again anyway)	bit UseInterrupts	; see if interupt use is turned on	bpl @SkipClear	; if not, then user has scan ints, so don't clear	jsr ClearSCB	; always clear the interupt flag no matter what.@SkipClear;; Copy new mouse location to direct page (before testing useInterrupts).; 24 Apr 89  SEG;	lda TheMouseX,s	sta NextMouseX	lda TheMouseY,s	sta NextMouseY;; Check the useinterrupts flag.;	bit UseInterrupts	bpl DoItNow;; Code was this:;	lda IntPending;	beq NoIntPending;	jsr ClearSCB;;NoIntPending; The next line would be needed if you put back the others.;	lda NextMouseY	; Get value back in Y. 24 Apr 89 SEG	cmp #200	; mouse positions greater than	bcc Less200	; 199 are treated as 0	lda #0Less200	tax	; note that I don't bother	lda >FirstSCB,x	; switching to 8 bit mode!	ora #%01000000	; turn on the int bit in this byte	sta >FirstSCB,x	lda #$8000	sta IntPending	bra CleanUpDoItNow	jsr HandleCursorCleanUp		; 	pld	pla	pla	phb	; put extra byte on	stack	plx	; pull bank and low	byte of rtl	ply	; pull high word of	rtl	pla	; pull off MouseY and ignore it	pla	; pull off MouseX and ignore it	phy	; put back high word of rtl	phx	; put back low byte	of rtl and bank	plb	; pull off bank	rtl	ENDP	title 'Refresh Cursor'*****************************************************************RefreshCursor	PROC EXPORT** This is the interrupt handling routine that is called* when a scan line interrupt occurs.** It is called in 8	bit native mode, and must return that way.** This routine must	clear the interrupt	flag in the scb.**** Inputs:*	direct page** Outputs:*	none** External Refs:	import HandleCursor** Entry Points:*	none*	longa on	; mode	longi on** Change History** 11 Nov 88	Steven Glass** Cursor is marked shielded if it was obscured and it was* supposed to be drawn but it was busy.  This prevents it from being undrawn* later when cursor is unshielded.*****************************************************************OrigDirect	equ 1WorkAreaRef	equ OrigDirect+2OrigP	equ WorkAreaRef+4RTLAdr	equ OrigP+2;------------------------------------------------------;; First switch to full native mode;	php	; save state	rep #$30;------------------------------------------------------;; Find our zero page.;	lda >WAPTPtr+2	pha	lda >WAPTPtr	pha	phd	tsc	tcd	ldy #16	lda [WorkAreaRef],y	clc	; now add $100	adc #$100	; and put in direct	reg	tcd;------------------------------------------------------;; Clear the interrupting SCB.;	jsr ClearSCB	jsr HandleCursor	pld	pla	pla	plp	; Now back in 8 bit	mode;------------------------------------------------------;; Now I have to clear the interrupt; by writing to the	interrupt status register in VGC; Bit 5 is the flag	for scan line ints.;	longa off	longi off	lda #%11011111	; clear bit 5	sta >ScanInt	;	clc	; tell the calling program	rtl	; that I serviced it.	longa on	longi on	ENDP	title 'HandleCursor'*****************************************************************HandleCursor	PROC** Called by both RefreshCursor and UpdateCursor to * undraw and draw the cursor on the screen.**** Inputs:*	all on d-page** Outputs:*	all on d-page** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 11 Dec 88	Steven Glass** Added on today to remove code duplication and make it* less costly to patch old ROM's.*****************************************************************;------------------------------------------------------;; Now see if we have to undraw.;	bit CursorFlags	bmi NotVis1	bit CursorLevel	bmi NotVis1	bit ObscureFlag	bmi NotVis1;-------------------------------------------------;; Undraw last one;	jsl UnDrawCursor;-------------------------------------------------;; Set new mouse pos;NotVis1	lda NextMouseY	sta MouseY	lda NextMouseX	sta MouseX	bit CursorLevel	bmi NotVis2	lda ObscureFlag	stz ObscureFlag	bit CursorFlags	bmi ForceUpdate;-------------------------------------------------;; Draw it in new place;	jsl DrawCursorNotVis2		; SkipIt		; 	bra CleanUpForceUpdate	tax	; was the cursor obscured?	beq @No	lda #shielded_m	; it was obscured, so now it must be considered	tsb CursorFlags	; as shielded.@No	lda #ForceU_M	; since i did not draw it	tsb CursorFlags	; force the draw at	time of;		; unshield cursorCleanUp		; 	rts	ENDP	title 'ClearSCB'*****************************************************************ClearSCB	PROC EXPORT** Clears the interrupt request from the SCB.*** Inputs:*	direct page.** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda NextMouseY	cmp #200	; mouse positions greater than	bcc Less200	; 199 are treated as 0	lda #0Less200	tax	; note that I don't bother	lda >FirstSCB,x	; switching to 8 bit mode!	and #%1111111110111111 ; turn off the int bit in this byte	sta >FirstSCB,x	stz IntPending	rts	ENDP	title 'DrawCursor'****************************************************************** iDrawCursor** What the hey, this draws the cursor at the position* indicated on zp.** Change History** 21 Aug 86     SEG	     The calculation of the saveRect was*	     wrong.  A test	for which mode branched*	     wrong for the 2 possible cases making*	     the 320 mode save rect too big and	the*	     640 mode save rect too small.**	     There is a calculation where I must add*	     8 to a value.	I know the carry is	set*	     so I saved a byte and added 7 without*	     touching the carry.** 2/1/89	Mensch** Added support for shadowed bank cursor...*****************************************************************iDrawCursor	PROC EXPORT	import ScreenTable;-------------------------------------------------;	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF; First we set up the bank.	phb	; save the current bank;; Find out if we are shadowed...	lda >$E0C035	; get the shadow register	and #$0008	; test the shadowing flags!	bne @1	; if zero, then shadowing is on	pea $0101	; push on the shadowed bank	bra @2@1	pea $E1E1	; push this on stack@2	plb	; set bank twice to	plb	; clear stack;-------------------------------------------------;; Next we set up the cursor rectangle	lda MouseY	sec	sbc HotSpot	sta CursorY1	sta SaveRect	sta CurrentY	clc	adc CurHeight	sta CursorY2	sta SaveRect+4	lda MouseX	sec	sbc HotSpot+2	sta CursorX1	sta SaveRect+2	lda CurWidth	; get width in words	asl a	; make it  bytes	asl a	; make it pixels for 320 mode	bit CursorMode-1	bpl Width320	; Fixed 21 Aug 86	asl aWidth320	clc	adc CursorX1	sta CursorX2	sta SaveRect+6;-----------------------------------------------;; Now I calculate the real bounds of the ; SaveRect.;  	clc	; clear carry for use later	lda #%1111111111111100 ; load a with mask for 320 mode	bit CursorMode-1	; check real mode	bpl Still320	; if not 320 mode put one more	asl a	; zero at low and and set carry!Still320	tay	; put copy of mask in y	and SaveRect+2	; and with left edge of rect	sta SaveRect+2	; and save it	tya	; get make back	and SaveRect+6	; and with right edge	bcs Still640	; if carry is clear	then we know	adc #4	; that we were in 320 mode	bra SaveRtEdge	; so add 4 and save	rt edgeStill640		; ; otherwise add 8	and save rt edge	adc #7	; note that carry was set to get here;		; and adding 7 with	carry set is like;		; adding 8. (sorry to those who follow);		; This changed on;		;    Aug 21, 1986;		; by SEGSaveRtEdge	sta SaveRect+6;-------------------------------------------------;; Set up the StartWord (we don't use FinishWord) then ; Figure out which preshifted image to use and put; pointer to it in CursorRef and MaskRef.;	bit CursorMode-1	bmi Mode640	lda CursorX1	; make x value into	byte	asl a	; get sign into c	lda CursorX1	ror a	; preserve sign	and #$FFFE	; make even	sta StartWord	lda CursorX1	; which preshifted image do I use?	and #3	bra GetReadyMode640		; 	lda CursorX1	; make x value into	byte	asl a	; get sign into c	php	; and save it	lda CursorX1	ror a	; preserve sign	plp	ror a	; rotate again preserving sign	and #$FFFE	; make even	sta StartWord	lda CursorX1	; determin which of	the preshifted	and #7	; images to useGetReady	asl a	; use number in a as index into	asl a	; pointers on zp	asl a	tax	lda CursorPtr,x	sta CursorRef	lda CursorPtr+1,x	sta CursorRef+1	lda MaskPtr,x	sta MaskRef	lda MaskPtr+1,x	sta MaskRef+1;-------------------------------------------------;; Set up other important vars for looping.;	lda SavePtr	; put the pointer to the beginning	sta SaveRef	; of the save area into SaveRef	lda SavePtr+1	; (which will be bumped for each 	sta SaveRef+1	; scan line)	lda CursorY1	sta CurrentY;-------------------------------------------------;; The Outer Loop;;    For each scan line (CursorY1 thru CursorY2);OuterLoop		; 	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	lda CurrentY	bpl NotAbove	jmp BumpVertCountersNotAbove	cmp #ScreenHeight	bmi NotBelow	jmp AllDoneNotBelow	cmp CursorY2	bmi YesDoIt	jmp AllDoneYesDoIt		; ;-------------------------------------------------;; Now I set up the loop to save the screen,; or in the mask and eor in the cursor all in; one loop;	lda CurWidth	; init the word count again (1 more	dec a	sta WordCount	; than before)	lda StartWord	; Screen Index starts at start word	sta ScreenIndex	lda CurrentY	; ScreenRef is created from current	asl a	; Y	tax	lda >ScreenTable,x	sta ScreenRef	stz SaveIndex	; Save index starts	at zeroDrawLoop	ldy ScreenIndex	; get screen index	bmi OffScrnH	; and see if it points ot real	cpy #ScreenWidth	; screen	bpl OffScrnH	lda (ScreenRef),y	; Save under cursor	ldy SaveIndex	; put in save buffer	sta [SaveRef],y	lda [MaskRef],y	; get word from mask	tyx	; save this here for quick access	ldy ScreenIndex	; get this back	ora (ScreenRef),y	; or with screen	txy	eor [CursorRef],y	; eor with rotated cursor	ldy ScreenIndex	sta (ScreenRef),y	; store in screen	inx	; bump this now that is in a register	inx	; register	stx SaveIndex	iny	; bump this now since it is in a	iny	; register	sty ScreenIndexFinishLoop	dec WordCount	; dec the word count and	bpl DrawLoop	; repeat till done	bra BumpVertCounters ; now bump vert countersOffScrnH	inc ScreenIndex	; These were not bumped	inc ScreenIndex	; in loop since cursor was clipped	inc SaveIndex	inc SaveIndex	bra FinishLoopBumpVertCounters		; 	inc CurrentY	lda CurWidth	; use this to calc width	asl a	tax	; save in x	clc	; add to cursor ref	adc CursorRef	sta CursorRef	txa	; add to mask ref	clc	adc MaskRef	sta MaskRef	txa	; inc once and add to SaveRef	inc a	inc a	clc	adc SaveRef	sta SaveRef	jmp OuterLoopAllDone	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	plb	; restore stack	rtl	ENDP	title 'UndrawCursor'****************************************************************** iUndrawCursor*** 2/1/89	Mensch** Added use of shadowed bank if shadowing is enabled...*****************************************************************iUndrawCursor	PROC EXPORT	import ScreenTable	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	phb	; save the current bank;; Find out if we are shadowed...	lda >$E0C035	; get the shadow register	and #$0008	; test the shadowing flags!	bne @1	; if zero, then shadowing is on	pea $0101	; push on the shadowed bank	bra @2@1	pea $E1E1	; push this on stack@2	plb	; set bank twice to	plb	; clear stack	lda CursorY1	sta CurrentY	lda SavePtr	sta SaveRef	lda SavePtr+1	sta SaveRef+1	stz SaveIndex	; start this at zero and do not reset itOuterLoop		; 	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	lda CurrentY	bpl NotAbove	jmp BumpVertCountersNotAbove	cmp #ScreenHeight	bmi NotBelow	jmp AllDoneNotBelow	cmp CursorY2	bmi YesDoIt	jmp AllDoneYesDoIt		; 	lda CurWidth	; init the word count	dec a	sta WordCount	lda StartWord	; Screen Index starts at start word	sta ScreenIndex	lda CurrentY	; ScreenRef is created from current	asl a	; Y	tax	lda >ScreenTable,x	sta ScreenRef	stz SaveIndex	; Save index starts	at zeroDrawLoop	ldy ScreenIndex	; get screen index	bmi OffScrnH	; and see if it points ot real	cpy #ScreenWidth	; screen	bpl OffScrnH	tyx	ldy SaveIndex	; get from save buffer	lda [SaveRef],y	iny	iny	sty SaveIndex	txy	sta (ScreenRef),y	; restore under cursor	iny	; bump this now since it is in a	iny	; register	sty ScreenIndexFinishLoop	dec WordCount	; dec the word count and	bpl DrawLoop	; repeat till done	bra BumpVertCounters ; now bump vert countersOffScrnH	inc ScreenIndex	; These were not bumped	inc ScreenIndex	; in loop since cursor was clipped	inc SaveIndex	inc SaveIndex	bra FinishLoopBumpVertCounters		; 	inc CurrentY	lda CurWidth	; use this to calc width	inc a	; of pixel maps	asl a	clc	adc SaveRef	sta SaveRef	jmp OuterLoopAllDone	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	plb	; restore stack	rtl	ENDP		title 'ScreenTable'ScreenTable 	PROC EXPORT	DC.W 0*160+ScreenStart	DC.W 1*160+ScreenStart	DC.W 2*160+ScreenStart	DC.W 3*160+ScreenStart	DC.W 4*160+ScreenStart	DC.W 5*160+ScreenStart	DC.W 6*160+ScreenStart	DC.W 7*160+ScreenStart	DC.W 8*160+ScreenStart	DC.W 9*160+ScreenStart	DC.W 10*160+ScreenStart	DC.W 11*160+ScreenStart	DC.W 12*160+ScreenStart	DC.W 13*160+ScreenStart	DC.W 14*160+ScreenStart	DC.W 15*160+ScreenStart	DC.W 16*160+ScreenStart	DC.W 17*160+ScreenStart	DC.W 18*160+ScreenStart	DC.W 19*160+ScreenStart	DC.W 20*160+ScreenStart	DC.W 21*160+ScreenStart	DC.W 22*160+ScreenStart	DC.W 23*160+ScreenStart	DC.W 24*160+ScreenStart	DC.W 25*160+ScreenStart	DC.W 26*160+ScreenStart	DC.W 27*160+ScreenStart	DC.W 28*160+ScreenStart	DC.W 29*160+ScreenStart	DC.W 3